import{_ as l,a0 as o,w as d,s as p,I as e,x as n,a1 as a,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 find 命令在 Linux 上查找文件和目錄 | LCTT x X-CMD","titleTemplate":false,"description":"使用 find 命令在 Linux 上查找文件和目錄 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 find 命令在 Linux 上查找文件和目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 find 命令在 Linux 上查找文件和目錄 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210909 Find files and directories on Linux with the find command","title":"使用 find 命令在 Linux 上查找文件和目錄","tag":"202112","desc":""},"relativePath":"202112/20210909 Find files and directories on Linux with the find command.md","filePath":"[post].md"}'),u={name:"202112/20210909 Find files and directories on Linux with the find command.md"};function f(m,s,h,g,b,k){const i=o("Link");return d(),p("div",null,[s[48]||(s[48]=e("h1",{id:"使用-find-命令在-linux-上查找文件和目錄",tabindex:"-1"},[n("使用 find 命令在 Linux 上查找文件和目錄 "),e("a",{class:"header-anchor",href:"#使用-find-命令在-linux-上查找文件和目錄","aria-label":"Permalink to “使用 find 命令在 Linux 上查找文件和目錄”"},"​")],-1)),s[49]||(s[49]=e("blockquote",null,[e("p",null,"學習 find 命令的原因有很多。")],-1)),s[50]||(s[50]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/11/083907eapzsopvcoc0ooro.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=n("不管我決心如何組織文件，似乎總有無法找到文件的時候。有時是因為我不記得最初的文件名，其他時候，我知道名字，但我不記得在哪裏保存它了。甚至有時我需要一個我最初就沒有創建的文件。但是，無論遇到什麼困難，我知道在 ",-1)),a(i,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:t(()=>[...s[0]||(s[0]=[n("POSIX 系統",-1)])]),_:1}),s[2]||(s[2]=n(" 上，總是有 ",-1)),s[3]||(s[3]=e("code",null,"find",-1)),s[4]||(s[4]=n(" 命令可以幫助我。",-1))]),s[51]||(s[51]=e("h3",{id:"安裝-find",tabindex:"-1"},[n("安裝 find "),e("a",{class:"header-anchor",href:"#安裝-find","aria-label":"Permalink to “安裝 find”"},"​")],-1)),e("p",null,[s[6]||(s[6]=e("code",null,"find",-1)),s[7]||(s[7]=n(" 命令由 ",-1)),a(i,{href:"https://pubs.opengroup.org/onlinepubs/9699919799.2018edition/"},{default:t(()=>[...s[5]||(s[5]=[n("POSIX 規範",-1)])]),_:1}),s[8]||(s[8]=n(" 定義，它創建了一個用於衡量 POSIX 系統的開放標準，這包括 Linux、BSD 和 macOS。簡而言之，只要你運行的是 Linux、BSD 或 macOS，那麼 ",-1)),s[9]||(s[9]=e("code",null,"find",-1)),s[10]||(s[10]=n(" 已經安裝了。",-1))]),e("p",null,[s[12]||(s[12]=n("但是，並非所有的 ",-1)),s[13]||(s[13]=e("code",null,"find",-1)),s[14]||(s[14]=n(" 命令都完全相同。例如，GNU 的 ",-1)),s[15]||(s[15]=e("code",null,"find",-1)),s[16]||(s[16]=n(" 命令有一些 BSD、Busybox 或 Solaris 上 ",-1)),s[17]||(s[17]=e("code",null,"find",-1)),s[18]||(s[18]=n(" 命令可能沒有或有但實現方式不同的功能。本文使用 ",-1)),a(i,{href:"https://www.gnu.org/software/findutils/"},{default:t(()=>[...s[11]||(s[11]=[n("findutils",-1)])]),_:1}),s[19]||(s[19]=n(" 包中的 GNU ",-1)),s[20]||(s[20]=e("code",null,"find",-1)),s[21]||(s[21]=n("，因為它很容易獲得且非常流行。本文演示的大多數命令都適用於 ",-1)),s[22]||(s[22]=e("code",null,"find",-1)),s[23]||(s[23]=n(" 的其他實現，但是如果你在 Linux 以外的平台上嘗試命令並得到非預期結果，嘗試下載並安裝 GNU 版本。",-1))]),s[52]||(s[52]=r(`<h3 id="按名稱查找文件" tabindex="-1">按名稱查找文件 <a class="header-anchor" href="#按名稱查找文件" aria-label="Permalink to “按名稱查找文件”">​</a></h3><p>你可以藉助正則表達式使用完整或部分的文件名來定位文件。<code>find</code> 命令需要你給出想搜索的目錄；指定搜索屬性選項，例如，<code>-name</code> 用於指定區分大小寫的文件名；然後是搜索字符串。默認情況下，搜索字符串按字面意思處理：除非你使用正則表達式語法，否則 <code>find</code> 命令搜索的文件名正是你在引號之間輸入的字符串。</p><p>假設你的 <code>Documents</code> 目錄包含四個文件：<code>Foo</code>、<code>foo</code>、<code>foobar.txt</code> 和 <code>foo.xml</code>。以下是對 <code>foo</code> 的字面搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -name &quot;foo&quot;</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo</span></span></code></pre></div><p>你可以使用 <code>-iname</code> 選項使其不區分大小寫來擴大搜索範圍：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -iname &quot;foo&quot;</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/Foo</span></span></code></pre></div><h3 id="通配符" tabindex="-1">通配符 <a class="header-anchor" href="#通配符" aria-label="Permalink to “通配符”">​</a></h3><p>你可以使用基本的 shell 通配符來擴展搜索。例如，<code>*</code> 表示任意數量的字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -iname &quot;foo*&quot;</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/Foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo.xml</span></span>
<span class="line"><span>/home/tux/Documents/examples/foobar.txt</span></span></code></pre></div><p><code>?</code> 表示單個字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -iname &quot;foo*.???&quot;</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo.xml</span></span>
<span class="line"><span>/home/tux/Documents/examples/foobar.txt</span></span></code></pre></div><p>這不是正則表達式語法，因此 <code>.</code> 在示例中只表示字母“點”。</p><h3 id="正則表達式" tabindex="-1">正則表達式 <a class="header-anchor" href="#正則表達式" aria-label="Permalink to “正則表達式”">​</a></h3><p>你還可以使用正則表達式。與 <code>-iname</code> 和 <code>-name</code> 一樣，也有區分大小寫和不區分大小寫的選項。但不一樣的是，<code>-regex</code> 和 <code>-iregex</code> 搜索應用於整個路徑，而不僅僅是文件名。這意味着，如果你搜索 <code>foo</code>，你不會得到任何結果，因為 <code>foo</code> 與 <code>/home/tux/Documents/foo</code> 不匹配。相反，你必須要麼搜索整個路徑，要麼在字符串的開頭使用通配符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -iregex &quot;.*foo&quot;</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/Foo</span></span></code></pre></div><h3 id="查找近一週修改過的文件" tabindex="-1">查找近一週修改過的文件 <a class="header-anchor" href="#查找近一週修改過的文件" aria-label="Permalink to “查找近一週修改過的文件”">​</a></h3><p>要查找近一週修改的文件，使用 <code>-mtime</code> 選項以及過去的天數（負數）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -mtime -7</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/Foo</span></span>
<span class="line"><span>/home/tux/Documents/examples/foo.xml</span></span>
<span class="line"><span>/home/tux/Documents/examples/foobar.txt</span></span></code></pre></div><h3 id="查找近幾天修改的文件" tabindex="-1">查找近幾天修改的文件 <a class="header-anchor" href="#查找近幾天修改的文件" aria-label="Permalink to “查找近幾天修改的文件”">​</a></h3><p>你可以結合使用 <code>-mtime</code> 選項來查找近幾天範圍內修改的文件。對於第一個 <code>-mtime</code> 參數，表示上一次修改文件的最近天數。第二個參數表示最大天數。例如，搜索修改時間超過 1 天但不超過 7 天的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -mtime +1 -mtime -7</span></span></code></pre></div><h3 id="按文件類型限制搜索" tabindex="-1">按文件類型限制搜索 <a class="header-anchor" href="#按文件類型限制搜索" aria-label="Permalink to “按文件類型限制搜索”">​</a></h3><p>指定查找文件的類型來優化 <code>find</code> 的結果是很常見的。如果你不確定要查找的內容，則不應該使用此選項。但如果你知道要查找的是文件而不是目錄，或者是目錄而不是文件，那麼這可能是一個很好的過濾器。選項是 <code>-type</code>，它的參數是代表不同類型數據的字母代碼。最常見的是：</p><ul><li><code>d</code> - 目錄</li><li><code>f</code> - 文件</li><li><code>l</code> - 鏈接文件</li><li><code>s</code> - 套接字</li><li><code>p</code> - 命名管道（用於 FIFO）</li><li><code>b</code> - 塊設備（通常是硬盤）</li></ul><p>下面是一些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~ -type d -name &quot;Doc*&quot;</span></span>
<span class="line"><span>/home/tux/Documents</span></span>
<span class="line"><span>$ find ~ -type f -name &quot;Doc*&quot;</span></span>
<span class="line"><span>/home/tux/Downloads/10th-Doctor.gif</span></span>
<span class="line"><span>$ find /dev -type b -name &quot;sda*&quot;</span></span>
<span class="line"><span>/dev/sda</span></span>
<span class="line"><span>/dev/sda1</span></span></code></pre></div><h3 id="調整範圍" tabindex="-1">調整範圍 <a class="header-anchor" href="#調整範圍" aria-label="Permalink to “調整範圍”">​</a></h3><p><code>find</code> 命令默認是遞歸的，這意味着它會在指定的目錄中層層搜索結果。這在大型文件系統中可能會變得不堪重負，但你可以使用 <code>-maxdepth</code> 選項來控制搜索深度：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /usr -iname &quot;*xml&quot; | wc -l</span></span>
<span class="line"><span>15588</span></span>
<span class="line"><span>$ find /usr -maxdepth 2 -iname &quot;*xml&quot; | wc -l</span></span>
<span class="line"><span>15</span></span></code></pre></div><p>也可以使用 <code>-mindepth</code> 設置最小遞歸深度：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /usr -mindepth 8 -iname &quot;*xml&quot; | wc -l</span></span>
<span class="line"><span>9255</span></span></code></pre></div><h3 id="下載速查表" tabindex="-1">下載速查表 <a class="header-anchor" href="#下載速查表" aria-label="Permalink to “下載速查表”">​</a></h3>`,32)),e("p",null,[s[26]||(s[26]=n("本文僅介紹 ",-1)),s[27]||(s[27]=e("code",null,"find",-1)),s[28]||(s[28]=n(" 的基本功能，它是一個很好的搜索工具，但對於強大的 ",-1)),a(i,{href:"https://opensource.com/article/18/5/gnu-parallel"},{default:t(()=>[...s[24]||(s[24]=[n("Parallel",-1)])]),_:1}),s[29]||(s[29]=n(" 命令來説，它也是一個非常有用的前端。學習 ",-1)),s[30]||(s[30]=e("code",null,"find",-1)),s[31]||(s[31]=n(" 的原因有很多，所以 ",-1)),a(i,{href:"https://opensource.com/downloads/linux-find-cheat-sheet"},{default:t(()=>[...s[25]||(s[25]=[n("下載我們免費的 ",-1),e("code",null,"find",-1),n(" 速查表",-1)])]),_:1}),s[32]||(s[32]=n(" 吧，它可以幫助你瞭解有關該命令的更多信息。",-1))]),s[53]||(s[53]=e("hr",null,null,-1)),e("p",null,[s[34]||(s[34]=n("via: ",-1)),a(i,{href:"https://opensource.com/article/21/9/linux-find-command"},{default:t(()=>[...s[33]||(s[33]=[n("https://opensource.com/article/21/9/linux-find-command",-1)])]),_:1})]),e("p",null,[s[39]||(s[39]=n("作者：",-1)),a(i,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[35]||(s[35]=[n("Seth Kenlon",-1)])]),_:1}),s[40]||(s[40]=n(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[36]||(s[36]=[n("lujun9972",-1)])]),_:1}),s[41]||(s[41]=n(" 譯者：",-1)),a(i,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[37]||(s[37]=[n("MjSeven",-1)])]),_:1}),s[42]||(s[42]=n(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[38]||(s[38]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[45]||(s[45]=n("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[43]||(s[43]=[n("LCTT",-1)])]),_:1}),s[46]||(s[46]=n(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[44]||(s[44]=[n("Linux中國",-1)])]),_:1}),s[47]||(s[47]=n(" 榮譽推出",-1))])])}const C=l(u,[["render",f]]);export{y as __pageData,C as default};
